  "stuSess.penaltyChoiceRefund": "I-refund sa ginamit na paraan ng pagbabayad",
  "stuSess.penaltyChoiceRefundDesc": "Para sa refund (€{amount}), makipag-ugnayan sa info@tutlio.lt. Kung nagbayad ka gamit ang card, maaari pa ring awtomatikong simulan ang refund sa Stripe.",
  "stuSess.creditAvailable": "Magagamit na credit",
  "stuSess.payWithCredit": "Magbayad gamit ang credit",
  "stuSess.creditAppliedSuccess": "Naidagdag ang €{amount} na credit sa iyong balanse at awtomatikong gagamitin sa susunod mong sesyon.",
  "stuSess.refundContactNote": "Para sa refund, makipag-ugnayan sa <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">May mga tanong o problema? Makipag-ugnayan sa <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Sinimulan na ang iyong refund sa Stripe.</p><p class=\"text-emerald-800 mt-1\">Karaniwang natatanggap ang refund sa card sa loob ng humigit-kumulang <strong>5–10 araw ng negosyo</strong> (maaaring mag-iba ayon sa bangko). Kung hindi mo ito matanggap sa karaniwang panahon, mag-email sa <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Mukhang hindi nabayaran ang sesyong ito sa Tutlio Stripe (hal. bank transfer o cash). Walang awtomatikong refund dito.</p><p class=\"mt-2\">Para ayusin ang refund, makipag-ugnayan sa iyong tutor na si <strong>{tutor}</strong> — gamitin ang email o mga detalye mula sa iyong mga booking o direkta mula sa tutor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Mukhang hindi nabayaran ang sesyong ito sa Tutlio Stripe (hal. bank transfer o cash). Walang awtomatikong refund dito.</p><p class=\"mt-2\">Dahil nag-aaral ka sa pamamagitan ng organisasyon, makipag-ugnayan sa <strong>administrator ng organisasyon</strong> (sa pamamagitan ng iyong tutor o ng mga inilathalang contact ng organisasyon).</p>",
  "stuSess.refundTutorFallback": "iyong tutor",
