  "blog.inlineCtaTitle": "Pamahalaan ang mga sesyon at estudyante sa iisang lugar",
  "blog.inlineCtaBody": "Pag-iskedyul, mga bayad, listahan ng naghihintay, at pakikipag-ugnayan sa magulang — lahat sa Tutlio.",
  "landing.heroSubtitle": "Pagbutihin ang mga operasyon at pagpapasya, at gawing mas mahusay ang trabaho sa mas matalinong pamamahala ng pagtuturo.",
  "landing.heroCta": "Magsimula nang libre",
  "landing.heroSpotAria": "Preview ng mahahalagang feature",
  "landing.heroSpot1Body": "Gumawa mismo ng mga sesyon o hayaang mag-book ang mga estudyante ng sarili nilang oras — lahat ay malinaw sa iisang lugar.",
  "landing.heroSpot2Body": "Iwasan ang kalat-kalat na tala — gawing awtomatiko ang pila at bawasan ang nawawalang kita dahil sa mga nakanselang sesyon.",
  "landing.heroMoreFeaturesCta": "Higit pang feature",
  "landing.trustText": "Pinagkakatiwalaan ng mga tutor at paaralan sa buong mundo.",
  "landing.heroLessonCount": "sesyon ang naiskedyul. Sumali sa amin at makatipid ng oras.",
  "landing.stepsTitle": "Magsimula sa 3 simpleng hakbang",
  "landing.stepsDesc": "Pasimplehin ang iyong mga gawain sa pagtuturo sa pag-set up ng profile, pag-aayos ng mga sesyon, at pagpapalago ng negosyo — lahat ay may tulong ng matalinong automation.",
  "landing.step1Title": "Gawin ang iyong profile",
  "landing.step1Desc": "I-set up ang workspace mo bilang tutor, idagdag ang mga asignatura, presyo, at bakanteng oras. Imbitahan ang mga estudyante para iisa ang impormasyong ginagamit ng lahat mula sa simula.",
  "landing.step2Title": "Ayusin ang iyong mga sesyon",
  "landing.step2Desc": "Gamitin ang kalendaryo, listahan ng naghihintay, at sistema ng pag-book para ayusin ang mga sesyon, punan ang mga bakante, at panatilihing maayos ang iskedyul mula simula hanggang dulo.",
  "landing.step3Title": "Tumanggap ng bayad at lumago",
  "landing.step3Desc": "Subaybayan ang mga bayad, magpadala ng mga invoice, at bantayan ang iyong pananalapi. Makamit ang mga resulta nang mas mabilis gamit ang maayos at tumpak na datos para sa iyong negosyo.",
  "landing.featuresHeading": "Pagbutihin ang iyong negosyo sa pagtuturo gamit ang ",
  "landing.featuresHighlight": "matalinong mga tool",
  "landing.featuresSubtitle": "Binibigyan ka ng aming platform ng mga tool para mag-iskedyul, mamahala, at magpalago ng negosyo sa pagtuturo upang mas mahusay kang makapagpasya at makapagtrabaho.",
  "landing.feat.scheduling": "Matalinong pag-iskedyul",
  "landing.feat.schedulingDesc": "Hayaang mag-book ang mga estudyante ng mga oras na itinakda mo at madaling pamahalaan ang iyong kalendaryo.",
  "landing.feat.schedulingHeading": "Ayusin at pagbutihin",
  "landing.feat.schedulingHighlight": "ang iyong iskedyul",
  "landing.feat.schedulingB1": "Hayaang mag-book mismo ang mga estudyante sa iyong mga bakanteng oras — wala nang paulit-ulit na palitan ng mensahe.",
  "landing.feat.schedulingB2": "Awtomatikong magtakda ng mga palugit sa pag-book at pahinga sa pagitan ng mga sesyon.",
  "landing.feat.schedulingB3": "Tingnan ang iyong buong lingguhan at buwanang kalendaryo na may lahat ng sesyon sa iisang lugar.",
  "landing.feat.waitlist": "Sistema ng listahan ng naghihintay",
  "landing.feat.waitlistDesc": "Awtomatikong punan ang mga nakanselang oras at huwag mawalan ng kita.",
  "landing.feat.waitlistHeading": "Huwag mawalan ng kita gamit ang",
  "landing.feat.waitlistHighlight": "matalinong listahan ng naghihintay",
  "landing.feat.waitlistB1": "Pumipila ang mga estudyante para sa gusto nilang oras — kapag may nagkansela, aabisuhan ang susunod sa pila.",
  "landing.feat.waitlistB2": "Mas maraming napupunang sesyon ang nangangahulugang mas kaunting nasasayang na oras at mas malaking kita.",
  "landing.feat.waitlistB3": "Awtomatikong inaasikaso ng system ang lahat — magtuturo ka na lang.",
  "landing.feat.payments": "Mga bayad at pananalapi",
  "landing.feat.paymentsDesc": "Mga bayad sa Stripe, invoice, at buwanang buod ng pananalapi sa iisang lugar.",
  "landing.feat.paymentsHeading": "Subaybayan at pamahalaan",
  "landing.feat.paymentsHighlight": "ang iyong pananalapi",
  "landing.feat.paymentsB1": "Tumanggap ng mga online na bayad sa Stripe — nagbabayad ang mga estudyante sa isang click.",
  "landing.feat.paymentsB2": "Agad na makita kung sino ang bayad na, sino ang may utang, at ang iyong kabuuang buwanang kita.",
  "landing.feat.paymentsB3": "Awtomatikong gumawa at magpadala ng mga invoice batay sa mga natapos na sesyon.",
  "landing.feat.reminders": "Matalinong mga paalala",
  "landing.feat.remindersHighlight": "Matalinong mga paalala",
  "landing.feat.remindersDesc": "Mga awtomatikong email para sa paalala sa sesyon, follow-up, at mga bayad na lampas na sa takdang petsa.",
  "landing.feat.remindersHeading": "Gawing awtomatiko gamit ang",
  "landing.feat.remindersB1": "Tumatanggap ang mga estudyante ng awtomatikong paalala bago ang bawat sesyon — mas kaunting hindi pagdalo.",
  "landing.feat.remindersB2": "Naipapadala ang mga abiso sa mga bayad na lampas na sa takdang petsa nang wala kang kailangang gawin.",
  "landing.feat.remindersB3": "Iangkop ang mga email sa iba't ibang kaganapan at uri ng estudyante.",
  "landing.analyticsAlt": "Dashboard ng pagsusuri at pananalapi sa Tutlio",
  "landing.optimizeTitle": "Ayusin at pagbutihin ",
