  "landing.optimizeBullet1": "I-sync ang iyong kalendaryo at makakuha ng 360° na pananaw sa iyong negosyo sa pagtuturo.",
  "landing.optimizeBullet2": "Subaybayan ang mga KPI gaya ng porsiyento ng napupunang sesyon, kita, at pagpapanatili ng mga estudyante.",
