  "landing.v2.bento2Sub": "Mga booking, invoice, at bayad gamit ang card — sa account ng estudyante o magulang, sa anumang device.",
  "landing.v2.bento3Title": "Pananalapi at pag-uulat sa iisang lugar",
  "landing.v2.bento3Sub": "Mga bayad, invoice, at buwanang buod ayon sa tutor — makita kung sino ang nakabayad na at sino ang huli.",
  "landing.v2.bento4Title": "Digital business card na may bakanteng oras",
  "landing.v2.bento4Sub": "Nakikita ng mga estudyante ang iyong mga presyo at bakanteng oras sa kalendaryo, pipili sila ng oras at magpapadala ng kahilingan — walang paulit-ulit na usapan.",
  "landing.v2.businessCardCta": "Tingnan kung paano ito gumagana",
  "landing.v2.bento4TitleBiz": "Pangkat, sahod, at mga account ng magulang",
  "landing.v2.bento4SubBiz": "Tingnan ang mga oras at sahod ng tutor, katayuan ng magulang, at mga invoice na lampas na sa takdang petsa — ang buong ahensya mo sa isang tingin.",
  "landing.v2.bento5Title": "Mga estudyante, magulang, at kasaysayan sa iisang lugar",
  "landing.v2.bento5Sub": "Mga tala, pagdalo, file, at bayad — isang database para sa buong paaralan o ahensya mo.",
  "landing.v2.pillarsTitle": "Apat na pundasyon. Isang sistema sa pagpapatakbo.",
  "landing.v2.pillarsSub": "Mga iskedyul ng tutor, account ng estudyante at magulang, invoice, at listahan ng naghihintay — isang daloy ng gawain nang hindi palipat-lipat ng tool.",
