  "orgTutorPolicy.title": "Mga panloob na patakaran para sa mga tutor",
  "orgTutorPolicy.intro": "Basahin ang mga panloob na patakaran ng organisasyon bago gamitin ang platform.",
  "orgTutorPolicy.acceptBtn": "Nauunawaan ko",
  "orgTutorPolicy.viewBtn": "Tingnan ang mga panloob na patakaran",
  "orgTutorPolicy.s1Title": "1. Pangkalahatang mga probisyon",
  "orgTutorPolicy.s1Body": "Saklaw ng mga patakarang ito ang iyong paggamit ng Tutlio platform (ang \"Platform\") bilang guro o tutor (ang \"Tutor\"). Inimbitahan kang gamitin ang Platform ng ahensya sa edukasyon, paaralan, o sentro ng pagtuturo na iyong kinakatawan (ang \"Organisasyon\"). Ang MB Tutlio ang nangangasiwa sa teknikal na pagpapanatili at suporta ng Platform. Sa paggamit ng iyong account, sumasang-ayon ka sa mga Patakarang ito at sa Patakaran sa privacy.",
  "orgTutorPolicy.s2Title": "2. Pamamahala ng account at mga iskedyul",
  "orgTutorPolicy.s2Intro": "Idinisenyo ang Platform para hindi mo na kailangang maglaan ng oras sa pakikipag-ugnayan sa mga estudyante tungkol sa oras ng sesyon.",
  "orgTutorPolicy.s2Link": "Natatanging link: Bibigyan ka ng personal na link sa pag-book ng sesyon (batay sa mga asignaturang itinuturo mo) na ginagamit ng mga estudyante sa pag-iskedyul ng sesyon.",
  "orgTutorPolicy.s2Calendar": "Pag-sync ng kalendaryo: Direktang nakadepende ang iyong bakanteng oras sa integrasyon ng Google Calendar (2-way sync). Personal mong pananagutan na tiyaking tumpak at napapanahon ang bakanteng oras na ipinapakita sa iyong kalendaryo. Hindi papayagan ng Platform na mag-book ang mga estudyante sa mga oras na minarkahang abala sa iyong kalendaryo.",
  "orgTutorPolicy.s2Security": "Seguridad ng account: Personal ang iyong account. Dapat mong panatilihing ligtas ang iyong mga detalye sa pag-login at huwag ibahagi ang mga ito sa mga ikatlong partido.",
  "orgTutorPolicy.s3Title": "3. Pagkansela ng mga sesyon at listahan ng naghihintay",
  "orgTutorPolicy.s3Intro": "Tumutulong ang Platform na masulit ang iyong iskedyul at maiwasan ang mga bakanteng oras:",
  "orgTutorPolicy.s3Auto": "Kung magkansela ng sesyon ang estudyante, awtomatikong nagpapadala ang Platform ng abiso (SMS/email) sa iba pang estudyante sa iyong listahan ng naghihintay, na nag-aalok ng nabakanteng oras. Wala ka nang kailangang karagdagang gawin.",
  "orgTutorPolicy.s3Rules": "Itinatakda ng iyong Organisasyon ang mga patakaran sa pagkansela ng sesyon (kung gaano kaaga maaaring magkansela at ang mga kahihinatnan).",
  "orgTutorPolicy.s4Title": "4. Pananalapi at mga bayad",
  "orgTutorPolicy.s4Intro": "Hindi mo kailangang mag-alala tungkol sa pag-invoice o pagkolekta ng bayad mula sa mga magulang:",
  "orgTutorPolicy.s4Advance": "Lahat ng bayad ng estudyante (o magulang) para sa iyong mga sesyon ay kinokolekta nang maaga sa Platform at direktang inililipat sa iyong Organisasyon.",
  "orgTutorPolicy.s4Confirmed": "Magtuturo ka lang ng sesyon kapag kumpirmado na ito sa system (ibig sabihin ay nasingil na ito).",
  "orgTutorPolicy.s4Contact": "Para sa iyong sahod, iskedyul ng payout, at iba pang usaping pinansyal, direktang makipag-ugnayan sa administrator ng iyong Organisasyon. Walang direktang transaksyong pinansyal ang MB Tutlio sa mga Tutor.",
  "orgTutorPolicy.s5Title": "5. Proteksyon ng datos ng estudyante (GDPR)",
  "orgTutorPolicy.s5Intro": "Bilang Tutor, may access ka sa personal na datos ng mga estudyante, panloob na tala, at mga materyal sa pag-aaral. Nangangako kang:",
  "orgTutorPolicy.s5Use": "Gagamitin lang ang datos na ito para sa pag-aayos at pagtuturo ng mga sesyon.",
  "orgTutorPolicy.s5NoCopy": "Hindi kokopyahin, ie-export, o ipamamahagi ang mga contact ng mga estudyante o magulang sa labas ng Platform.",
  "orgTutorPolicy.s5Notes": "Pangangalagaan ang mga panloob na rekord ng Organisasyon (mga tala sa progreso ng estudyante) na ikaw at ang administrasyon lang ng Organisasyon ang makakakita, hindi ang mga estudyante o magulang.",
  "orgTutorPolicy.s5Termination": "Kapag natapos ang iyong ugnayan sa trabaho sa Organisasyon, agad na babawiin ang iyong access sa datos na ito.",
  "orgTutorPolicy.s6Title": "6. Teknikal na operasyon at limitasyon ng pananagutan",
  "orgTutorPolicy.s6Body": "Ipinagbabawal ang paggamit ng Platform para sa labag sa batas na layunin, pamamahagi ng mga mapaminsalang link sa materyal ng sesyon, o anumang panggugulo sa system. Tinitiyak ng MB Tutlio ang operasyon at teknikal na pagpapanatili ng Platform pero hindi nito pananagutan ang mga abalang dulot ng iyong koneksyon sa internet, sira sa device, o maling pag-set up ng Google Calendar.",
  "orgTutorPolicy.s7Title": "7. Suporta at mga contact",
  "orgTutorPolicy.s7Org": "Para sa mga tanong tungkol sa iskedyul ng sesyon, sahod, pagtatalaga ng estudyante, o pag-aayos ng trabaho, makipag-ugnayan sa administrator ng iyong Organisasyon.",
  "orgTutorPolicy.s7Tech": "Para sa mga teknikal na error sa Platform (hindi gumaganang pag-sync ng kalendaryo, hindi pagtanggap ng mga abiso), ipaalam sa administrator ng iyong Organisasyon, na makikipag-ugnayan sa pangkat ng teknikal na suporta ng Tutlio.",
  "register.orgPolicyConsent": "Sa paggamit ng aming platform, sumasang-ayon ka sa",
  "register.orgPolicyLink": "mga panloob na patakaran",
